#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdint.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // absolute values (handle LLONG_MIN safely)
    long a_abs = a < 0 ? (a == LLONG_MIN ? LLONG_MAX : -a) : a;
    long b_abs = b < 0 ? (b == LLONG_MIN ? LLONG_MAX : -b) : b;
    // range check (absolute values must be <= 1,000,000)
    if (a_abs > 1000000L || b_abs > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Euclidean algorithm for GCD
    long x = a_abs;
    long y = b_abs;
    while (y != 0) {
        long r = x % y;
        x = y;
        y = r;
    }
    long gcd = x; // if both inputs are 0, gcd == 0
    // LCM calculation with overflow detection
    long lcm;
    if (gcd == 0) {
        lcm = 0;
    } else {
        long div = a_abs / gcd;
        __int128 prod = ( (__int128) div ) * b_abs;
        if (prod > LLONG_MAX || prod < LLONG_MIN) {
            puts("OVERFLOW");
            return 0;
        }
        lcm = (long) prod;
    }
    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
